using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed to "$type" in EF9.
            // Existing 500K documents use "Discriminator", and raw SQL queries
            // reference c.Discriminator. Keep the old name for backward compat.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — EF9 id values no longer include the discriminator
            // prefix.  EF8 wrote "Product|123"; EF9 defaults to "123".
            // Preserve old format so existing documents remain readable.
            entity.Property<string>("__id")
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();

            // BREAKING CHANGE 3 — HasIndex() now throws for the Cosmos provider.
            // It was a silent no-op in EF8.  Removed.
            // entity.HasIndex(p => p.Sku);
        });
    }
}

/// <summary>
/// Generates id values in the EF8 format: "{Discriminator}|{PrimaryKey}".
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override string Next(EntityEntry entry)
    {
        var discriminator = entry.Metadata.GetDiscriminatorValue()?.ToString();
        var pk = entry.Property("Id").CurrentValue;
        return $"{discriminator}|{pk}";
    }

    public override bool GeneratesTemporaryValues => false;
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

