using Microsoft.EntityFrameworkCore;

class CosmosQuery
{
    // BREAKING CHANGE 4 — Sync I/O (ToList, First, Single, etc.) now throws
    // InvalidOperationException in the EF9 Cosmos provider.  Use async.
    async Task FindProductsAsync(ProductContext ctx)
    {
        // Raw SQL referencing c.Discriminator is safe because we explicitly
        // kept the old discriminator property name in OnModelCreating.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        var products = await ctx.Products
            .Where(p => p.Sku == "ABC")
            .ToListAsync();
    }
}

